public class DateExtractorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("two dates, first wins", "2024-03-15",
                DateExtractor.firstDate("Due 2024-03-15, not 2024-04-01."));
        check("whole text is a date", "2019-12-31",
                DateExtractor.firstDate("2019-12-31"));
        check("no dates at all", null,
                DateExtractor.firstDate("no dates here"));
        check("too few digits does not match", null,
                DateExtractor.firstDate("short date 7-04-01 today"));
        check("date embedded in other characters", "2023-01-07",
                DateExtractor.firstDate("log(2023-01-07)end"));
        check("find skips a partial match", "1999-08-24",
                DateExtractor.firstDate("ids 1234-56 then 1999-08-24 ok"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

