public class DateExtractor {

    public static String firstDate(String text) {
        java.util.regex.Pattern datePattern = java.util.regex.Pattern.compile("\\d{4}-\\d{2}-\\d{2}");
        java.util.regex.Matcher m = datePattern.matcher(text);
        if (m.find()) {
            return m.group();
        }
        return null;
    }
}
